// CF1780D. At most 12 subtractions for a 30-bit secret.
// --verify runs exhaustive small inputs and samples the whole 10^9 range.
#include <algorithm>
#include <array>
#include <cassert>
#include <cstdlib>
#include <iostream>
#include <map>
#include <numeric>
#include <random>
#include <set>
#include <string>
#include <vector>
using namespace std;
int weight(int x){return __builtin_popcount(unsigned(x));}
struct Hypothesis{int d,gamma;};
struct Node{int probe=0,leaf=-1;map<int,int> children;};
struct Tree{
    vector<Node> nodes;
    int modulus=64;
    bool terminal=false;
    int build(const vector<Hypothesis>& s,int last,int depth){
        if(all_of(s.begin(),s.end(),[&](auto h){return h.d==s[0].d;})){
            int id=nodes.size();nodes.push_back({0,s[0].d,{}});return id;
        }
        if(!depth)return -1;
        int limit=modulus-1;
        if(terminal)for(auto h:s)limit=min(limit,h.d);
        struct Option{int worst,x;map<int,vector<Hypothesis>> groups;};
        vector<Option> options;
        for(int x=last+1;x<=limit;++x){
            Option opt{0,x,{}};
            map<int,set<int>> distinct;
            for(auto h:s){
                int delta=weight((h.d-x+modulus)%modulus)-weight(h.d)+(h.d<x?h.gamma:0);
                opt.groups[delta].push_back(h);distinct[delta].insert(h.d);
            }
            if(opt.groups.size()<2)continue;
            for(auto& entry:distinct)opt.worst=max(opt.worst,int(entry.second.size()));
            options.push_back(move(opt));
        }
        sort(options.begin(),options.end(),[](auto& a,auto& b){return make_pair(a.worst,a.x)<make_pair(b.worst,b.x);});
        for(auto& opt:options){
            int id=nodes.size();nodes.push_back({opt.x,-1,{}});
            bool ok=true;
            for(auto& [answer,bucket]:opt.groups){
                int child=build(bucket,opt.x,depth-1);
                if(child<0){ok=false;break;}
                nodes[id].children[answer]=child;
            }
            if(ok)return id;
            nodes.resize(id);
        }
        return -1;
    }
};
Tree block;map<pair<int,int>,Tree> endgame;
