const string alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
int decode(Tree& t,const vector<int>& states,int last,int depth,int initial,
           const string& probes,size_t& pos){
    int id=t.nodes.size();
    if(states.size()==1){t.nodes.push_back({0,states.front(),{}});return id;}
    if(depth==0)abort();
    int x=states.front();
    if(states.size()>size_t(depth+1)){
        x=0;
        for(int i=0;i<3;++i){
            if(pos==probes.size())abort();
            auto val=alphabet.find(probes[pos++]);
            if(val==string::npos)abort();
            x=64*x+int(val);
        }
    }
    if(x<=last || x>states.front())abort();
    array<vector<int>,19> groups;
    for(int y:states)groups[weight(y-x)].push_back(y);
    t.nodes.push_back({x,-1,{}});
    for(int v=0;v<=18;++v)if(!groups[v].empty()){
        int child=decode(t,groups[v],x,depth-1,initial,probes,pos);
        t.nodes[id].children[v-initial]=child;
    }
    return id;
}
void prepare(){
    vector<Hypothesis> all;
    for(int d=0;d<64;++d)for(int g=-1;g<=23;++g)all.push_back({d,g});
    if(block.build(all,0,3)!=0)abort();
    array<vector<int>,19> groups;
    for(int d=0;d<(1<<18);++d)groups[weight(d)].push_back(d);
    for(int p=7;p<=17;++p){
        size_t pos=0;
        const string& data=terminal_probes[p-7];
        decode(endgame[{18,p}],groups[p],0,6,p,data,pos);
        if(pos!=data.size())abort();
    }
}
template<class Oracle>
int solve(int count,Oracle subtract){
    int shift=0,spent=0,low=0;
    auto ask=[&](int x){spent+=x;count=subtract(x);return count;};
    while(shift<30){
        int w=30-shift,p=count-weight(low);
        if(p==0)return spent+low;
        if(p==w)return spent+low+(((1<<w)-1)<<shift);
        if(p<=6){
            int base=spent,start=0,recovered=0;
            for(int i=0;i<p;++i){
                int before=count;
                ask(1<<(shift+start));
                int found=start+count-before+1;
                recovered|=1<<found;start=found+1;
            }
            return base+low+(recovered<<shift);
        }
        const Tree& t=w==18?endgame.at({w,p}):block;
        int base=spent,initial_count=count,id=0,previous=0;
        while(t.nodes[id].leaf<0){
            int x=t.nodes[id].probe;
            int delta=ask((x-previous)<<shift)-initial_count;
            id=t.nodes[id].children.at(delta);previous=x;
        }
        int d=t.nodes[id].leaf;
        if(w==18)return base+low+(d<<shift);
        low+=((d-previous+64)%64)<<shift;
        shift+=6;
    }
    return spent+low;
}
int main(int argc,char**){
    prepare();
    if(argc>1){
        int worst=0,witness=0;
        auto check=[&](int original){
            int cur=original,calls=0;
            int decoded=solve(weight(cur),[&](int x){
                if(x<=0||x>cur)abort();
                cur-=x;++calls;return weight(cur);
            });
            if(decoded!=original||calls>12)abort();
            if(calls>worst){worst=calls;witness=original;}
        };
        for(int v=1;v<=1000000;++v)check(v);
        mt19937 rng(23474);
        for(int i=0;i<1000000;++i)check(1+int(rng()%1000000000));
        cout<<"2000000 cases; observed maximum "<<worst<<" at "<<witness<<endl;return 0;
    }
    {
        int p;cin>>p;
        int original=solve(p,[](int x){cout<<"- "<<x<<endl;int r;if(!(cin>>r)||r<0)exit(0);return r;});
        cout<<"! "<<original<<endl;
    }
}
